package com.exampro.controller;import com.exampro.dto.ApiDtos.*;import com.exampro.service.AttemptService;import jakarta.validation.Valid;import java.security.Principal;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class AttemptController {private final AttemptService s;public AttemptController(AttemptService s){this.s=s;}@PostMapping("/exams/{examId}/attempts") public ResponseEntity<AttemptResponse> start(Principal p,@PathVariable Long examId){return ResponseEntity.status(HttpStatus.CREATED).body(s.start(p.getName(),examId));}@PutMapping("/attempts/{id}/answers") public AttemptResponse save(Principal p,@PathVariable Long id,@Valid @RequestBody SaveAnswersRequest r){return s.save(p.getName(),id,r);}@PostMapping("/attempts/{id}/submit") public AttemptResponse submit(Principal p,@PathVariable Long id){return s.submit(p.getName(),id);}@GetMapping("/results/my") public List<AttemptResponse> mine(Principal p){return s.mine(p.getName());}@GetMapping("/results/{id}") public ResultResponse result(Principal p,@PathVariable Long id){return s.result(p.getName(),id,false);}@GetMapping("/admin/results") @PreAuthorize("hasRole('ADMIN')") public List<ResultResponse> all(){return s.allResults();}}
